import json,sys
S=sys.argv[1]; liste=[int(x) for x in sys.argv[2].split(",")]
plan=json.load(open(S+'/ki-plan.json')); ids=json.load(open(S+'/ki-ids.json'))
EN={'alpenrosen':'pink alpine roses in front of a pine tree and a mountain under blue sky','apollo':'a holiday apartment living room with a black leather corner sofa, a dining table and "Dream Lounge" lettering on the wall','apollo-haus':'two photos side by side of the same apartment house with wooden balconies, in summer on the left and in snowy winter on the right','apollo-kueche':'a small fitted kitchen with yellow tiles and a ceramic hob','apollo-wohnen':'an apartment living and dining room with a black sofa and "Dream Lounge" lettering on the wall','arizona':'an apartment living room with a red sofa and armchairs and a coffee table','arizona-haus':'two photos side by side of two apartment houses with wooden balconies in a mountain village','arizona-holz':'a pine wood bedroom with a double bed and bedside lamps','arizona-wohnen':'an apartment living room with a red sofa, white walls and big windows','bach':'a small mountain lake with snowy peaks and a modern house behind','balkon':'the view from a wooden hotel balcony down into a sunny snowy alpine valley','bergbach':'a mountain stream between large granite boulders','blumen':'a turquoise mountain lake in a green alpine valley','dorf-fluss':'a snowy mountain village beside a frozen river and snow-covered fir trees','dorf-nacht':'a mountain village lit at night in a snowy valley at blue hour','dorf-weiss':'a snowy mountain village with chalets under fresh snow','dorf-winter':'a snowy valley with a mountain village and a hotel in winter sun','fr-detail':'a breakfast buffet with jars of jam on small plates, bread and butter','fr-tisch':'a hotel breakfast buffet table with bread baskets, jams and a glass-covered cold-cut display','gletscher':'snowy glaciers and mountains under clear blue sky','gondel':'two old cable car gondolas decorated with fairy lights in front of a restaurant at night','haus-sommer-g':'a four-storey alpine hotel with wooden balconies and a sun terrace in summer under blue sky','haus-winter-b':'a four-storey alpine hotel with wooden balconies in deep snow under blue sky','haus-winter-g':'a four-storey alpine hotel with wooden balconies in snow under blue sky','huette':'an old wooden hut in deep snow with fir trees and mountains','mattmark':'a turquoise reservoir lake in a high alpine valley','metro':'an underground funicular railway car with "Saas-Fee" lettering at a station with red-white steps','murmeltiere':'two marmots touching noses on a rock with green grass','roesti-orange':'a rustic restaurant with orange tablecloths and warm wooden ceiling','roesti-raum':'a rustic wooden restaurant room with tables and potato sacks printed with lettering on the wall','roesti-stube':'a rustic wooden restaurant room with potato sacks on the wall and wooden tables','roesti-tische':'a rustic restaurant with wooden tables, a stone wall and hanging lamps','see-blumen':'yellow flowers on the shore of a turquoise mountain lake with a waterfall','spa-holz':'a rustic wooden log sauna with stacked log walls and warm light','spa-wasser':'two photos side by side: a relaxation room with a lounger and a stone wall, and an indoor swimming pool','speiseraum':'a traditional hotel dining room with white tablecloths, wooden chairs, lanterns and bullseye glass windows','spielburg':'an inflatable bouncy castle with red towers in front of a hotel in summer','stausee':'a turquoise reservoir lake with snowy mountains','stube-tische':'a traditional hotel dining room with wooden panelling, tables and lamps','stuebli':'a small wooden raclette room with bullseye glass panes and wooden tables','tal-dorf':'a mountain village in a green valley seen from above, with forest and peaks','tal-sommer':'a mountain village in a green alpine valley seen from above, with forest and snowy peaks','wasserfall':'a waterfall rushing between grey rocks','winterbach':'a frozen stream in a snowy forest','z-abend':'a hotel double room in the evening with warm bedside lamps and wooden furniture','z-bad':'a hotel bathroom with a washbasin, mirror and window','z-balkon':'a hotel room balcony door with a view of snowy fir trees and a small table','z-bogen':'a hotel double room with a wooden bed under a sloped wooden ceiling','z-dach':'a hotel room under a sloped wooden ceiling with a double bed and a sofa','z-doppel':'a hotel double room with a dark headboard and an orange curtain','z-einzel':'a small single hotel room with a bed and window','z-familie':'two connected hotel rooms with an open door between them','z-fenster':'a hotel double room with tall windows and orange curtains','z-gelb':'a bright hotel double room with a wooden bed and an orange picture','z-hell':'a bright hotel double room with wooden furniture and a TV','z-licht':'a hotel double room with a dark headboard, a red sofa and a round table','z-neu':'a hotel double room with a desk and a TV','z-rot':'a hotel double room with a red armchair and a round table','z-sessel':'a hotel room with a red sofa seating corner and a double bed','z-tv':'a hotel room with a double bed, a TV and a balcony door','z-twin':'a hotel room with two single beds and warm lamps','z-wanne':'a hotel bathroom with a bathtub, tiles and a window'}
AUSSEN={'alpenrosen','apollo-haus','arizona-haus','bach','balkon','bergbach','blumen','dorf-fluss','dorf-nacht','dorf-weiss','dorf-winter','gletscher','gondel','haus-sommer-g','haus-winter-b','haus-winter-g','huette','mattmark','murmeltiere','see-blumen','spielburg','stausee','tal-dorf','tal-sommer','wasserfall','winterbach','z-balkon'}
NEU={'arizona':'an apartment bedroom with a wide double bed with pastel patterned duvets, a low wooden bed frame, two round wall lamps, a window with white net curtains and beige drapes, a small framed picture on the wall',
 'arizona-haus':'two photos side by side of two apartment houses with wooden balconies; the left photo has a pale white overcast sky, the right photo has a forested slope behind the house',
 'blumen':'a clear mountain stream with smooth rounded pale grey boulders, fir trees, a wooden pylon and snowy peaks under blue sky; the water is clear and grey-green',
 'apollo-kueche':'a small fitted kitchen with one smooth glossy yellow glass splashback panel without any tile joints, a ceramic hob, a stainless steel sink and white cabinets'}
EN.update(NEU)
GENERISCH={k for k in EN if k.startswith('z-')}|{'stube-tische','roesti-orange','roesti-stube','roesti-tische','stuebli','speiseraum'}
for k in GENERISCH: EN[k]='the very same hotel interior as in the reference photo'
out=[]
for i in liste:
    p=plan[i]; k=p['key']
    s=(f"Recreate this exact photograph 1:1 as a new, tack-sharp high-resolution photo taken with a professional full-frame camera: {EN[k]}. "
       "The same scene, the same camera angle, framing and perspective; every object, window, picture, building, tree, rock and mountain stays exactly where it is, with the same shape, size and colour"
       + (", the same sky, the same weather and the same time of day" if k in AUSSEN else "") + ". Any lettering stays exactly as it is. Crisp fine texture and detail everywhere, clean natural light, natural colours.")
    out.append({'index':i,'params':{'model':'gpt_image_2_5','quality':'high','resolution':'2k','aspect_ratio':p['ar'],'medias':[{'role':'image_references','value':ids[k]}],'prompt':s}})
print(json.dumps(out,ensure_ascii=False))
